source(file.path(dirname(sub('^--file=', '', commandArgs(FALSE)[grepl('^--file=', commandArgs(FALSE))])), 'analysis_common.R'))
suppressPackageStartupMessages(library(ggplot2))
read_result<-function(n)read_csv(file.path(results_dir,paste0(n,'.csv')))
fmt<-function(x,d=0)formatC(x,format='f',digits=d,big.mark=',')
fci<-function(lo,hi,d=2)paste0('[',fmt(lo,d),', ',fmt(hi,d),']')
label<-function(x)unname(comp_labels[x])
s<-read_result('sample');d<-read_result('dual_counts');g<-read_result('prospective_output_gaps');pr<-read_result('prediction_performance');pc<-read_result('promotion_cox');ps<-read_result('promotion_sample');ld<-read_result('promotion_landmark_differences')
stopifnot(pc[scope=='pooled',players]==sum(ps$entrants),nrow(read_result('threshold_grid'))==1080)
tab<-s[,.(Competition=label(comp),Period=paste(first_year,last_year,sep='--'),Matches=fmt(matches),Players=fmt(players),`Dual role`=fmt(allround_role),Evaluable=fmt(evaluable))]
tex_table(tab,'sample','Accepted observations and workload roles','tab:sample','Men\'s records through 31 December 2025. Players are distinct within competitions and may appear in more than one row. County first-class includes the Championship and the 2020--21 Bob Willis Trophy. Dual role requires 20 actual batting innings, modal position at most seven, and 2,000/1,000/500 scorecard balls in long-format/ODI/T20I cricket. Evaluable requires 20 batting innings and either 20 wickets or 500 balls. Active careers remain in the sample.')
tab<-merge(d[floor_quantile==.5],d[floor_quantile==.75,.(comp,upper_quartile=independent)],by='comp');tab<-tab[match(names(configs),comp)]
tex_table(tab[,.(Competition=label(comp),Evaluable=fmt(eligible),Independence=independent,`All couplings`=frechet_certain,`Some coupling`=frechet_possible,`75th floor`=upper_quartile)],'dual','Dual high output depends on the benchmark and posterior coupling','tab:dual','All counts use a joint probability threshold of 0.5. Median specialist floors apply except in the final column, which uses 75th-percentile floors and independence. All/some couplings give the lower/upper classification counts allowed by the marginal posterior probabilities. These are conditional model bounds, not confidence limits or verified ability labels. Bowling output is era-priced wickets in long formats and signed run containment in limited overs.')
# Table 3 reports the models with shared exposure predictors (39_feedback_checks.R);
# the no-exposure losses and the second split are in the appendix.
fx<-read_result('feedback_forecast_exposure')[split=='Baseline' & exposure==TRUE]
pred<-dcast(fx,comp+outcome~model,value.var='rmse');setorder(pred,comp,outcome)
pred[,ord:=match(comp,names(configs))];setorder(pred,ord,outcome)
tex_table(pred[,.(Competition=label(comp),Outcome=ifelse(outcome=='future_bat_annual','Runs/year','Wickets/year'),`Exposure only`=fmt(exposure_only,1),Role=fmt(workload,1),`Average gap`=fmt(traditional,1),`Share/RCA`=fmt(share,1),`Separate inputs`=fmt(continuous,1))],'prediction','Forecast error on later cohorts','tab:prediction','Entries are root mean squared errors; lower is better. Predictors use the first 30 appearances. Every model includes four shared exposure terms: log days from debut to the 30th appearance, appearances in the preceding year, and early runs and wickets per year. The exposure-only model contains these terms alone; the other models add the stated predictors. Targets are total output in completed matches during the next five calendar years, divided by five, including zero subsequent play. Training outcomes end before test-cohort landmarks begin. Share and RCA have identical matched spline bases and predictions. The conventional model retains separate batting and wicket rates and bowling participation. These are descriptive forecast comparisons, not tests of model superiority.')
g[,ord:=match(comp,names(configs))];setorder(g,ord,discipline)
tex_table(g[,.(Competition=label(comp),Outcome=ifelse(discipline=='bat','Runs/match','Wickets/match'),`Dual n`=allround_n,`Reference n`=reference_n,Gap=fmt(difference,2),`95% CI`=fci(lower,upper),`Holm p`=fmt(p_holm_primary,3))],'gaps','Subsequent output: early dual roles relative to specialist roles','tab:gaps','Role is measured in the first 30 appearances; output is measured over the next five years among players with subsequent appearances in the test cohorts. Separate comparisons use batting specialists for runs and bowling specialists for wickets, controlling for landmark decade. Intervals use CR2 entry-team clustering with Satterthwaite degrees of freedom. Holm adjustment retains the planned family of ten contrasts; two T20 contrasts are unestimated because only three dual-role players qualify. Units are native scorecard units. Associations do not identify a causal cost of specialisation.')
tex_table(pc[,.(Sample=ifelse(scope=='pooled','Pooled',label(scope)),Entrants=fmt(players),Events=events,HR=fmt(HR,2),`95% CI`=fci(lower,upper),Clubs=clusters)],'promotion','First-Test transitions within five years of domestic entry','tab:promotion','Hazard ratios compare the time-updated dual role with the batting role. All predictors use completed earlier matches; entrants do not have to survive to a fixed appearance count. Models adjust flexibly for past matches, batting and wicket rates, and entry decade, and stratify by entry competition. Intervals use delete-one entry-club jackknife standard errors and a t reference with clubs minus one degrees of freedom. These are descriptive associations for first Test appearances for any country, with age and national eligibility unobserved. Constant hazard ratios are summaries; proportionality diagnostics are reported in Appendix A7.')
lr<-read_result('promotion_landmark_risks')
tex_table(lr[role%in%c('Batting role','All-round role'),.(Competition=label(comp),Role=ifelse(role=='Batting role','Batting','Dual'),Players=n,Events=events,`Risk (%)`=fmt(100*risk,1),`95% interval`=fci(100*lower,100*upper,1))],'landmark','First-Test risk between years two and five','tab:landmark','Separate landmark estimand: players must be alive and without a Test appearance at year two. Roles use only information available then. Aalen--Johansen cumulative incidence treats recorded death as competing and the data cutoff as censoring. Intervals are percentile intervals from 300 player resamples. Between-role risk differences use 1,000,000 entry-team resamples for county cricket and the exact multinomial bootstrap distribution over six Shield teams (462 allocations), and are reported in the text; none establishes equivalence within five percentage points.')
grid<-read_result('threshold_grid')
gs<-grid[,.(min_count=min(independent),max_count=max(independent),min_fraction=min(independent/eligible),max_fraction=max(independent/eligible)),by=.(comp,activity,floor_quantile)]
put(gs,'threshold_grid_summary')
tex_table(gs[activity=='All observed',.(Competition=label(comp),Floor=ifelse(floor_quantile==.5,'Median','75th'),`Count range`=paste(min_count,max_count,sep='--'),`Percent range`=paste(fmt(100*min_fraction,1),fmt(100*max_fraction,1),sep='--'))],'grid','Joint threshold sensitivity','tab:grid','Within each floor, ranges cross 15/20/25 innings, three bowling-exposure minima, actual/nominal position and joint-probability cutoffs 0.3/0.5/0.7. Priors, role pools and floors are re-estimated. The five axes give 108 cells; repeating the grid after excluding 2025 appearances\' players gives 216 per competition. The latter is an absence convention, not observed retirement.')
ws<-read_result('whiteball_reference_sensitivity')
tex_table(ws[,.(Format=label(comp),Pool=ifelse(pool=='All countries','All','Twelve countries'),Percentile=fmt(100*percentile),Eligible=evaluable,Independence=independent,`Coupling range`=paste(certain,possible,sep='--'))],'whiteball','Limited-overs reference populations and economy percentiles','tab:whiteball','All reference economies, era scales, specialist pools and priors are rebuilt. The fixed twelve-country subset uses match-level team identity and the twelve countries listed in Appendix A4; it is not historical ICC membership. Conditional posterior counts use median floors and probability 0.5.')
bc<-read_result('bowling_margin_decomposition')
tex_table(bc[role%in%c('All-round role','Bowling role'),.(Format=label(comp),Role=ifelse(role=='All-round role','Dual','Bowling'),Players=n,Participation=fmt(bowling_participation,2),`Balls/used match`=fmt(balls_conditional,1),`Wickets/6 balls`=fmt(wickets_per_six_balls,3),`Wickets/match`=fmt(wickets_per_match,2))],'margins','Three margins of subsequent bowling output','tab:margins','Test cohorts and five-year future windows as in Table 4. These rows use common aggregate appearance weights: participation times conditional balls times wickets per ball equals wickets per appearance exactly. They therefore differ from the equally player-weighted regression means. The T20 dual-role row has only three players and is descriptive.')
cal<-read_result('eb_future_calibration')[nominal_coverage==.95]
tex_table(cal[,.(Format=label(comp),Outcome=ifelse(discipline=='bat_runs','Runs','Wickets'),Players=n,`95% coverage`=fmt(100*observed_coverage,1),`RMSE`=fmt(root_mean_square_error,2))],'calibration','Predictive checks for a constant player-output model','tab:calibration','Training-only Gaussian random-intercept priors use native output in first-30-match histories. Coverage concerns later per-match means, conditional on subsequent play and its observed exposure. It checks transport across career stages, not the calibration of unobserved ability. Undercoverage cautions against literal interpretations of the retrospective posterior classifications.')
boot<-read_result('dual_bootstrap')
bs<-boot[,.(lo=quantile(independent,.025),hi=quantile(independent,.975),expected_lo=quantile(expected,.025),expected_hi=quantile(expected,.975),converged=sum(converged)),by=comp];put(bs,'bootstrap_summary')
tex_table(bs[,.(Format=label(comp),`Count interval`=paste(fmt(lo),fmt(hi),sep='--'),`Expected-count interval`=paste(fmt(expected_lo,1),fmt(expected_hi,1),sep='--'),Converged=converged)],'bootstrap','Sensitivity to estimated floors and prior parameters','tab:bootstrap','Percentile ranges from 200 joint player resamples per competition, re-estimating both marginal priors and specialist medians. Reference decade currencies and scales are held fixed. The resampling assumes exchangeable player records and is conditional on the audited inclusion rules; the table is not a population census confidence interval.')
pred2<-pr[outcome=='future_dual'];pred2<-dcast(pred2,comp~model,value.var='brier')
tex_table(pred2[,.(Format=label(comp),Role=fmt(workload,3),`Average gap`=fmt(traditional,3),`Share/RCA`=fmt(share,3),`Separate inputs`=fmt(continuous,3))],'brier','Forecasting future dual output','tab:brier','Brier scores for exceeding training-only median specialist annual-output floors in both disciplines. Logistic models use a fixed ridge penalty of one on standardised slopes, avoiding separation; the intercept is unpenalised. T20 is omitted because specialist training pools do not both reach 30 players. Lower values indicate lower squared probability error; no superiority test is claimed.')
ad<-read_result('additive_output_index');aw<-read_result('feedback_additive_index_weighting')
aw<-dcast(aw,comp~weighting,value.var=c('index','lower','upper'));ad<-merge(ad[,.(comp,allround_n)],aw,by='comp');ad<-ad[match(names(configs),comp)]
tex_table(ad[,.(Format=label(comp),`Dual n`=allround_n,`Pooled`=fmt(`index_Appearance-pooled`,2),`Pooled CI`=fci(`lower_Appearance-pooled`,`upper_Appearance-pooled`),`Weighted`=fmt(`index_Player-weighted`,2),`Weighted CI`=fci(`lower_Player-weighted`,`upper_Player-weighted`))],'index','Additive specialist-relative native output','tab:index','Sum of the dual-role group\'s batting output relative to the batting-role group and its wickets relative to the bowling-role group, per appearance, in the held-out cohorts. Pooled entries divide group totals by group appearances, the weighting used in Table~\\ref{tab:margins}; weighted entries average each player\'s own rates. Confidence intervals (CI, 95 per cent) use an entry-team delete-one jackknife. The index omits fielding, specialist secondary output, constrained bowling opportunities and team production.',align='lrrrrr')
colours<-c('Tests'='#5C2346','County first-class'='#3D8EB9','Sheffield Shield'='#D4A03E','ODIs'='#45808B','T20Is'='#6B8E5E')
theme_set(theme_minimal(base_size=16)+theme(text=element_text(family='Times New Roman',face='plain',colour='#333333'),panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),legend.position='bottom',legend.title=element_blank(),strip.text=element_text(face='plain'),plot.title=element_text(face='plain')))
saveplot<-function(plot,name,width=9,height=5){ggsave(file.path(revision_dir,'paper/figures',paste0(name,'.pdf')),plot,width=width,height=height,device=cairo_pdf);ggsave(file.path(revision_dir,'paper/figures',paste0(name,'.png')),plot,width=width,height=height,dpi=300)}
ref<-read_result('reference_prices');ref[,Format:=label(comp)]
plot<-ggplot(ref[comp%in%c('tests','county','sheffield')],aes(decade,wicket_price,colour=Format,linetype=Format))+geom_line(linewidth=.7)+geom_point(size=1.5)+scale_colour_manual(values=colours)+labs(x='Calendar decade',y='Bowler-conceded runs\nper credited wicket')
saveplot(plot,'wicket_prices',9,4.6)
plot<-ggplot(grid[activity=='All observed'],aes(factor(probability_cutoff),100*independent/eligible,colour=factor(floor_quantile)))+geom_point(position=position_jitter(width=.1,height=0,seed=2412),alpha=.35,size=1.3)+facet_wrap(~factor(comp,levels=names(configs),labels=unname(comp_labels)),nrow=1)+scale_colour_manual(values=c('#5C2346','#3D8EB9'),labels=c('Median specialist floor','75th-percentile floor'))+labs(x='Joint-probability threshold',y='Evaluable players classified (%)')
saveplot(plot,'threshold_sensitivity',10,4.4)
plot<-ggplot(g,aes(x=difference,y=factor(label(comp),levels=rev(unname(comp_labels)))))+geom_vline(xintercept=0,colour='#777777',linetype='dashed')+geom_errorbar(aes(xmin=lower,xmax=upper),orientation='y',width=.2,colour='#5C2346')+geom_point(size=2,colour='#5C2346')+facet_wrap(~factor(discipline,levels=c('bat','bowl'),labels=c('Runs per match','Wickets per match')),scales='free_x')+labs(x='Dual role minus specialist role (95% interval)',y=NULL)
saveplot(plot,'prospective_gaps',9,4.8)
macros<-c(TotalPlayers=fmt(sum(s$players)),TotalMatches=fmt(sum(s$matches)),TotalAppearances=fmt(sum(s$appearances)),CountyPlayers=fmt(s[comp=='county',players]),CountyMatches=fmt(s[comp=='county',matches]),PromotionEntrants=fmt(sum(ps$entrants)),PromotionEvents=fmt(sum(ps$Test_events)),EarlyEvents=fmt(sum(ps$events_first_two_years)),PromotionHR=fmt(pc[scope=='pooled',HR],2),PromotionLow=fmt(pc[scope=='pooled',lower],2),PromotionHigh=fmt(pc[scope=='pooled',upper],2),CountyRiskGap=fmt(100*ld[comp=='county',difference],1),CountyRiskLow=fmt(100*ld[comp=='county',lower],2),CountyRiskHigh=fmt(100*ld[comp=='county',upper],2),ShieldRiskGap=fmt(100*ld[comp=='sheffield',difference],1),ShieldRiskLow=fmt(100*ld[comp=='sheffield',lower],2),ShieldRiskHigh=fmt(100*ld[comp=='sheffield',upper],2))
writeLines(paste0('\\newcommand{\\',names(macros),'}{',macros,'}'),file.path(revision_dir,'paper/results_macros.tex'))
cat('Generated manuscript tables, figures and number macros from final result files\n')
